81: /// Zero-Turn Memory Priming: compiles strictly static SystemMessage from Persona, AGENTS.md, Skills, and Tool Instructions.
82: /// Strictly static System Prompt: Zero dynamic timestamps, zero random UUIDs in the System prompt to prevent cache invalidation.
83: /// Dynamic context (task ID, title, description, worktree path) belongs exclusively in the user message.
84: pub async fn compile_primed_system_prompt(
85:     repo_root: &Path,
86:     role: &str,
87: ) -> Result<String> {
88:     let mut sections = Vec::new();
89: 
90:     // 1. Role Persona
91:     let persona_file = repo_root.join(".cvh").join("agents").join(format!("{}.md", role));
92:     if persona_file.exists() {
93:         if let Ok(persona_text) = tokio::fs::read_to_string(&persona_file).await {
94:             sections.push(format!("# Role Persona: {}\n\n{}", role, persona_text.trim()));
95:         }
96:     } else {
97:         sections.push(format!("# Role Persona: {}\nYou are an expert AI agent in {}.", role, role));
98:     }
99: 
100:     // 2. Project Guidelines & Invariants (AGENTS.md)
101:     let agents_md = repo_root.join("AGENTS.md");
102:     if agents_md.exists() {
103:         if let Ok(agents_text) = tokio::fs::read_to_string(&agents_md).await {
104:             sections.push(format!("# Architectural Invariants & Guidelines\n\n{}", agents_text.trim()));
105:         }
106:     }
107: 
108:     // 3. Skills Repository
109:     let skills_dir = repo_root.join(".agents").join("skills");
110:     if skills_dir.exists() {
111:         let mut skills_summary = Vec::new();
112:         if let Ok(mut entries) = tokio::fs::read_dir(&skills_dir).await {
113:             let mut entries_vec = Vec::new();
114:             while let Ok(Some(entry)) = entries.next_entry().await {
115:                 entries_vec.push(entry);
116:             }
117:             // Deterministic sort of skills
118:             entries_vec.sort_by_key(|e| e.file_name());
119: 
120:             for entry in entries_vec {
121:                 if entry.file_type().await.map(|t| t.is_dir()).unwrap_or(false) {
122:                     let skill_name = entry.file_name().to_string_lossy().to_string();
123:                     let skill_doc = entry.path().join("SKILL.md");
124:                     if skill_doc.exists() {
125:                         if let Ok(content) = tokio::fs::read_to_string(&skill_doc).await {
126:                             skills_summary.push(format!("### Skill `{}`\n{}", skill_name, content.trim()));
127:                         }
128:                     }
129:                 }
130:             }
131:         }
132:         if !skills_summary.is_empty() {
133:             sections.push(format!("# Active Agent Skills\n\n{}", skills_summary.join("\n\n")));
134:         }
135:     }
136: 
137:     // 4. Tool Instructions (SWE-bench Industrial Suite)
138:     sections.push(
139:         "# Scoped Tool Execution Mandate\n\
140:         You have direct tool access scoped to your isolated worktree. \
141:         Use `read_file`, `write_file`, `edit_file`, `glob`, `grep`, and `execute_command` to inspect, modify, and verify code. \
142:         Always use Ground Truth Sensors (e.g. `cargo check`, `npm run build`) via `execute_command` to verify changes.\n\
143:         When finished, output your comprehensive final answer."
144:             .to_string(),
145:     );
146: 
147:     Ok(sections.join("\n\n---\n\n"))
148: }
